def sort_even(l: list):
    even_indices = sorted(l[i] for i in range(len(l)) if i % 2 == 0)
    result = l[:]
    for i, val in enumerate(result):
        if i % 2 == 0:
            result[i] = even_indices.pop(0)
    return result

